import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <ATen/ATen.h>
#include <ATen/cuda/CUDAContext.h>

__global__ void cross_entropy_kernel(const half* __restrict__ logits,
                                     const int64_t* __restrict__ targets,
                                     float* __restrict__ loss,
                                     int batch,
                                     int num_classes) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= batch) return;

    const half* row = logits + (size_t)idx * num_classes;
    int64_t target = targets[idx];

    // 1) find max for numerical stability
    float max_val = -FLT_MAX;
    for (int c = 0; c < num_classes; ++c) {
        float v = __half2float(row[c]);
        if (v > max_val) max_val = v;
    }

    // 2) compute sum of exp(logit - max)
    float sum_exp = 0.0f;
    for (int c = 0; c < num_classes; ++c) {
        float v = __half2float(row[c]) - max_val;
        sum_exp += expf(v);
    }

    // 3) log-sum-exp
    float log_sum_exp = logf(sum_exp) + max_val;

    // 4) loss_i = log_sum_exp - logit_target
    float logit_target = __half2float(row[target]);
    float loss_i = log_sum_exp - logit_target;

    // 5) atomic accumulate
    atomicAdd(loss, loss_i);
}

torch::Tensor cross_entropy_fp16(torch::Tensor logits,
                                 torch::Tensor targets) {
    TORCH_CHECK(logits.is_cuda(), "logits must be CUDA tensor");
    TORCH_CHECK(targets.is_cuda(), "targets must be CUDA tensor");
    TORCH_CHECK(logits.dtype() == torch::kHalf, "logits must be fp16");
    TORCH_CHECK(targets.dtype() == torch::kLong, "targets must be int64");
    TORCH_CHECK(logits.dim() == 2, "logits must be 2-D (batch, classes)");
    TORCH_CHECK(targets.dim() == 1, "targets must be 1-D (batch,)");

    int batch = logits.size(0);
    int num_classes = logits.size(1);

    auto loss = torch::zeros({1}, torch::dtype(torch::kFloat32).device(logits.device()));

    const int threads = 256;
    const int blocks = (batch + threads - 1) / threads;

    AT_DISPATCH_FLOATING_TYPES_AND_HALF(logits.scalar_type(), "cross_entropy_fp16", ([&] {
        cross_entropy_kernel<<<blocks, threads>>>(
            logits.data_ptr<half>(),
            targets.data_ptr<int64_t>(),
            loss.data_ptr<float>(),
            batch,
            num_classes);
    }));

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        throw std::runtime_error(std::string("CUDA kernel error: ") + cudaGetErrorString(err));
    }

    // average over batch
    loss = loss / static_cast<float>(batch);
    return loss;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("cross_entropy_fp16", &cross_entropy_fp16, "Cross Entropy (fp16 inputs) CUDA");
}
'''

ext = load_inline(name='cross_entropy_fp16_ext',
                  cpp_sources='',
                  cuda_sources=src,
                  functions=['cross_entropy_fp16'],
                  verbose=False)

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, predictions: torch.Tensor, targets: torch.Tensor) -> torch.Tensor:
        # predictions: (B, C) fp16, targets: (B,) int64
        return ext.cross_entropy_fp16(predictions, targets)

# Example usage (mirrors reference get_inputs):
if __name__ == "__main__":
    batch_size = 32768
