    preds = torch.rand(batch_size, num_classes, dtype=torch.half, device='cuda')
    targs = torch.randint(0, num_classes, (batch_size,), dtype=torch.long, device='cuda')
    model = ModelNew().cuda()
    loss = model(preds, targs)
